    public static byte[] png(String name) {
        return switch (name) {
            case "cross" -> decode(CROSS_0);
            case "crown" -> decode(CROWN_0);
            case "dollar" -> decode(DOLLAR_0);
            case "heart" -> decode(HEART_0);
            case "lighting" -> decode(LIGHTING_0);
            case "line" -> decode(LINE_0);
            case "point" -> decode(POINT_0);
            case "rhombus" -> decode(RHOMBUS_0);
            case "snowflake" -> decode(SNOWFLAKE_0);
            case "star" -> decode(STAR_0);
            case "triangle" -> decode(TRIANGLE_0);
            case "diamond" -> decode(DIAMOND_0);
            case "white" -> decode(WHITE_0);
            default -> throw new IllegalArgumentException(name);
        };
    }

    public static String[] names() {
        return new String[]{"cross", "crown", "dollar", "heart", "lighting", "line", "point", "rhombus", "snowflake", "star", "triangle", "diamond", "white"};
    }

    private static byte[] decode(String... parts) {
        int total = 0;
        byte[][] decoded = new byte[parts.length][];
        for (int i = 0; i < parts.length; i++) {
            decoded[i] = Base64.getDecoder().decode(parts[i]);
            total += decoded[i].length;
        }
        byte[] out = new byte[total];
        int o = 0;
        for (byte[] d : decoded) {
            System.arraycopy(d, 0, out, o, d.length);
            o += d.length;
        }
        return out;
    }
